const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const normalize = (value) =>
  text(value)
    .toLowerCase()
    .replace(/ي/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/\u200c/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const requestedAction =
  text(input.action || 'auto').toLowerCase();
const raw_message = text(input.raw_message);
const normalizedMessage = normalize(raw_message);
const channel = text(input.channel).toLowerCase();
const actor_name = text(input.actor_name || 'patient');
const source_channel =
  text(input.source_channel || channel || 'api').toLowerCase();
const policy_version =
  text(input.policy_version || '1.0');
const reason = text(input.reason);
const confirm_action = bool(input.confirm_action);

const explicitActions = [
  'auto',
  'opt_out_all',
  'opt_out_marketing',
  'opt_in_contact',
  'opt_in_marketing',
  'disable_channel',
  'enable_channel',
  'get_status',
];

const stopPatterns = [
  /(^|\s)stop($|\s)/i,
  /unsubscribe/i,
  /لغو/,
  /توقف/,
  /پیام نده/,
  /پیام نفرست/,
  /عدم دریافت/,
  /دیگه.*پیام/,
  /لا ترسل/,
  /الغاء الاشتراك/,
  /إلغاء الاشتراك/,
];

const marketingPatterns = [
  /تبلیغ/,
  /بازاریابی/,
  /marketing/i,
  /promotional/i,
  /اعلان تجاری/,
];

let action = requestedAction;
let requires_confirmation = false;
let interpretation = 'explicit_action';

if (requestedAction === 'auto') {
  const stopDetected = stopPatterns.some(
    (pattern) => pattern.test(normalizedMessage)
  );

  const marketingDetected =
    marketingPatterns.some(
      (pattern) => pattern.test(normalizedMessage)
    );

  if (stopDetected) {
    action = marketingDetected
      ? 'opt_out_marketing'
      : 'opt_out_all';
    interpretation = 'deterministic_opt_out_detected';
  } else {
    action = 'needs_confirmation';
    requires_confirmation = true;
    interpretation = 'message_not_safely_interpreted';
  }
}

const channels = [
  'whatsapp',
  'sms',
  'email',
  'phone',
  'web_push',
  'in_app',
];

const sourceChannels = [
  'web',
  'whatsapp',
  'telegram',
  'sms',
  'email',
  'phone',
  'manual',
  'api',
  'system',
];

const errors = [];

if (!explicitActions.includes(requestedAction)) {
  errors.push({
    field: 'action',
    message: 'اقدام معتبر نیست.',
  });
}

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (
  ['disable_channel', 'enable_channel'].includes(action) &&
  !channels.includes(channel)
) {
  errors.push({
    field: 'channel',
    message: 'کانال ارتباطی معتبر نیست.',
  });
}

if (!sourceChannels.includes(source_channel)) {
  errors.push({
    field: 'source_channel',
    message: 'کانال منبع معتبر نیست.',
  });
}

if (
  requestedAction === 'auto' &&
  !raw_message
) {
  errors.push({
    field: 'raw_message',
    message: 'برای تشخیص خودکار، متن پیام الزامی است.',
  });
}

if (
  action !== 'get_status' &&
  action !== 'needs_confirmation' &&
  confirm_action !== true
) {
  errors.push({
    field: 'confirm_action',
    message: 'تغییر وضعیت ارتباط باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    mobile,
    requested_action: requestedAction,
    action,
    raw_message,
    channel,
    actor_name,
    source_channel,
    policy_version,
    reason:
      reason || raw_message,
    confirm_action,
    interpretation,
    requires_confirmation,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
